content.content:
  1	package com.loja.repository;
  2	
  3	import com.fasterxml.jackson.core.JsonProcessingException;
  4	import com.fasterxml.jackson.databind.ObjectMapper;
  5	import com.loja.domain.*;
  6	
  7	import java.sql.*;
  8	import java.time.Instant;
  9	import java.util.*;
 10	
 11	public class OrderRepository {
 12	    private final Database database;
 13	    private final ObjectMapper objectMapper;
 14	
 15	    public OrderRepository(Database database, ObjectMapper objectMapper) {
 16	        this.database = database;
 17	        this.objectMapper = objectMapper;
 18	    }
 19	
 20	    public void save(Order order, Connection conn) throws SQLException {
 21	        String sql = """
 22	            INSERT INTO orders (id, customer_cpf, customer_email, zip_code, region, shipping_method,
 23	                               coupon, payment_method, club_tier, status, created_at, tracking_code,
 24	                               payment_transaction_id, summary_json)
 25	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?::json)
 26	        """;
 27	
 28	        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
 29	            pstmt.setString(1, order.getId());
 30	            pstmt.setString(2, order.getCustomerCpf());
 31	            pstmt.setString(3, order.getCustomerEmail());
 32	            pstmt.setString(4, order.getZipCode());
 33	            pstmt.setString(5, order.getRegion().name());
 34	            pstmt.setString(6, order.getShippingMethod().name());
 35	            pstmt.setString(7, order.getCoupon());
 36	            pstmt.setString(8, order.getPaymentMethod().name());
 37	            pstmt.setString(9, order.getClubTier().name());
 38	            pstmt.setString(10, order.getStatus().name());
 39	            pstmt.setTimestamp(11, Timestamp.from(order.getCreatedAt()));
 40	            pstmt.setString(12, order.getTrackingCode());
 41	            pstmt.setString(13, order.getPaymentTransactionId());
 42	            pstmt.setString(14, objectMapper.writeValueAsString(order.getSummary()));
 43	            pstmt.executeUpdate();
 44	        } catch (JsonProcessingException e) {
 45	            throw new SQLException("Failed to serialize summary", e);
 46	        }
 47	
 48	        String itemSql = "INSERT INTO order_items (order_id, sku, quantity) VALUES (?, ?, ?)";
 49	        try (PreparedStatement pstmt = conn.prepareStatement(itemSql)) {
 50	            for (OrderItem item : order.getItems()) {
 51	                pstmt.setString(1, order.getId());
 52	                pstmt.setString(2, item.getSku());
 53	                pstmt.setInt(3, item.getQuantity());
 54	                pstmt.addBatch();
 55	            }
 56	            pstmt.executeBatch();
 57	        }
 58	    }
 59	
 60	    public Optional<Order> findById(String id) {
 61	        String sql = "SELECT * FROM orders WHERE id = ?";
 62	        try (Connection conn = database.getConnection();
 63	             PreparedStatement pstmt = conn.prepareStatement(sql)) {
 64	            pstmt.setString(1, id);
 65	            try (ResultSet rs = pstmt.executeQuery()) {
 66	                if (rs.next()) {
 67	                    Order order = mapOrder(rs);
 68	                    loadItems(order, conn);
 69	                    return Optional.of(order);
 70	                }
 71	            }
 72	        } catch (SQLException e) {
 73	            throw new RuntimeException("Failed to find order", e);
 74	        }
 75	        return Optional.empty();
 76	    }
 77	
 78	    public Optional<Order> findByIdForUpdate(String id, Connection conn) throws SQLException {
 79	        String sql = "SELECT * FROM orders WHERE id = ? FOR UPDATE";
 80	        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
 81	            pstmt.setString(1, id);
 82	            try (ResultSet rs = pstmt.executeQuery()) {
 83	                if (rs.next()) {
 84	                    Order order = mapOrder(rs);
 85	                    loadItems(order, conn);
 86	                    return Optional.of(order);
 87	                }
 88	            }
 89	        }
 90	        return Optional.empty();
 91	    }
 92	
 93	    public void updateStatus(String orderId, OrderStatus status, Connection conn) throws SQLException {
 94	        String sql = "UPDATE orders SET status = ? WHERE id = ?";
 95	        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
 96	            pstmt.setString(1, status.name());
 97	            pstmt.setString(2, orderId);
 98	            pstmt.executeUpdate();
 99	        }
100	    }
101	
102	    public void updateTrackingCode(String orderId, String trackingCode, Connection conn) throws SQLException {
103	        String sql = "UPDATE orders SET tracking_code = ? WHERE id = ?";
104	        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
105	            pstmt.setString(1, trackingCode);
106	            pstmt.setString(2, orderId);
107	            pstmt.executeUpdate();
108	        }
109	    }
110	
111	    public void updatePaymentTransaction(String orderId, String transactionId, Connection conn) throws SQLException {
112	        String sql = "UPDATE orders SET payment_transaction_id = ? WHERE id = ?";
113	        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
114	            pstmt.setString(1, transactionId);
115	            pstmt.setString(2, orderId);
116	            pstmt.executeUpdate();
117	        }
118	    }
119	
120	    public boolean hasCompletedOrders(String cpf, Connection conn) throws SQLException {
121	        String sql = "SELECT COUNT(*) FROM orders WHERE customer_cpf = ? AND status IN ('PAID', 'SHIPPED', 'DELIVERED')";
122	        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
123	            pstmt.setString(1, cpf);
124	            try (ResultSet rs = pstmt.executeQuery()) {
125	                rs.next();
126	                return rs.getInt(1) > 0;
127	            }
128	        }
129	    }
130	
131	    public boolean recordPaymentTransaction(String orderId, String transactionId, Instant paidAt, Connection conn) throws SQLException {
132	        String sql = "INSERT INTO payment_transactions (order_id, transaction_id, paid_at) VALUES (?, ?, ?) ON CONFLICT DO NOTHING";
133	        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
134	            pstmt.setString(1, orderId);
135	            pstmt.setString(2, transactionId);
136	            pstmt.setTimestamp(3, Timestamp.from(paidAt));
137	            int inserted = pstmt.executeUpdate();
138	            return inserted > 0;
139	        }
140	    }
141	
142	    private void loadItems(Order order, Connection conn) throws SQLException {
143	        String sql = "SELECT * FROM order_items WHERE order_id = ?";
144	        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
145	            pstmt.setString(1, order.getId());
146	            try (ResultSet rs = pstmt.executeQuery()) {
147	                List<OrderItem> items = new ArrayList<>();
148	                while (rs.next()) {
149	                    items.add(new OrderItem(
150	                        rs.getString("sku"),
151	                        rs.getInt("quantity")
152	                    ));
153	                }
154	                order.setItems(items);
155	            }
156	        }
157	    }
158	
159	    private Order mapOrder(ResultSet rs) throws SQLException {
160	        Order order = new Order();
161	        order.setId(rs.getString("id"));
162	        order.setCustomerCpf(rs.getString("customer_cpf"));
163	        order.setCustomerEmail(rs.getString("customer_email"));
164	        order.setZipCode(rs.getString("zip_code"));
165	        order.setRegion(Region.valueOf(rs.getString("region")));
166	        order.setShippingMethod(ShippingMethod.valueOf(rs.getString("shipping_method")));
167	        order.setCoupon(rs.getString("coupon"));
168	        order.setPaymentMethod(PaymentMethod.valueOf(rs.getString("payment_method")));
169	        order.setClubTier(ClubTier.valueOf(rs.getString("club_tier")));
170	        order.setStatus(OrderStatus.valueOf(rs.getString("status")));
171	        order.setCreatedAt(rs.getTimestamp("created_at").toInstant());
172	        order.setTrackingCode(rs.getString("tracking_code"));
